parameters.jsCode:
const order = $input.first().json;
const items = JSON.parse(order.items || '[]');
const itemList = items.map(i => `• ${i.name} | Size UK${i.sz} | Qty: ${i.qty} | ₹${(i.price*i.qty).toLocaleString('en-IN')}`).join('
');

return [{
  json: {
    ...order,
    items_formatted: itemList,
    order_date: new Date(order.created_at).toLocaleString('en-IN', {timeZone: 'Asia/Kolkata', day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit'}),
    total_formatted: '₹' + order.total_amount.toLocaleString('en-IN'),
    telegram_message: `🛍️ *NEW ORDER — HYPE*

👤 *Customer:* ${order.customer_name}
📱 *Phone:* ${order.phone}
📧 *Email:* ${order.email || 'N/A'}

📦 *Items:*
${itemList}

💰 *Total: ₹${order.total_amount.toLocaleString('en-IN')}*
💳 *Payment:* ${order.payment_status.toUpperCase()}

🏠 *Delivery Address:*
${order.address}

🕐 *Time:* ${new Date(order.created_at).toLocaleString('en-IN', {timeZone: 'Asia/Kolkata'})}

#Order${order.id}`
  }
}];

